import { useEffect, useRef, useState, useCallback } from 'react';

export const LIVE_REFRESH_MS = 15000;

// Refresh reads only: no activity timestamp is generated by background polling.
export default function useLiveRefresh(load, apply, { enabled = true, paused = false } = {}) {
    const applyRef = useRef(apply);
    applyRef.current = apply;
    const runRef = useRef(null);
    const previousLoad = useRef(null);
    const loaded = useRef(false);
    const [loading, setLoading] = useState(true);
    const [refreshing, setRefreshing] = useState(false);
    const [error, setError] = useState('');
    const [lastUpdated, setLastUpdated] = useState(null);

    useEffect(() => {
        let cancelled = false;
        let busy = false;
        let controller;
        if (previousLoad.current !== load) {
            loaded.current = false;
            previousLoad.current = load;
            setLastUpdated(null);
            setError('');
        }
        setRefreshing(false);
        if (!enabled || paused) { setLoading(false); return undefined; }
        setLoading(!loaded.current);

        const refresh = async (manual = false) => {
            if (cancelled || busy || (!manual && document.hidden)) return;
            if (navigator.onLine === false) {
                setError('You are offline. Reconnecting will update this page.');
                setLoading(false);
                return;
            }
            busy = true;
            controller = new AbortController();
            setRefreshing(true);
            try {
                const data = await load(controller.signal);
                if (cancelled) return;
                applyRef.current(data);
                loaded.current = true;
                setLastUpdated(new Date());
                setError(navigator.onLine === false ? 'You are offline. Reconnecting will update this page.' : '');
            } catch (err) {
                if (!cancelled && err.code !== 'ERR_CANCELED' && err.name !== 'AbortError') {
                    setError('Could not update this page. Displayed values may be outdated. Retrying automatically.');
                }
            } finally {
                busy = false;
                if (!cancelled) { setLoading(false); setRefreshing(false); }
            }
        };
        runRef.current = refresh;
        const whenVisible = () => refresh();
        const whenOffline = () => setError('You are offline. Reconnecting will update this page.');
        refresh();
        const timer = setInterval(whenVisible, LIVE_REFRESH_MS);
        document.addEventListener('visibilitychange', whenVisible);
        window.addEventListener('focus', whenVisible);
        window.addEventListener('online', whenVisible);
        window.addEventListener('offline', whenOffline);
        return () => {
            cancelled = true;
            controller?.abort();
            runRef.current = null;
            clearInterval(timer);
            document.removeEventListener('visibilitychange', whenVisible);
            window.removeEventListener('focus', whenVisible);
            window.removeEventListener('online', whenVisible);
            window.removeEventListener('offline', whenOffline);
        };
    }, [load, enabled, paused]);

    const refresh = useCallback(() => runRef.current?.(true), []);
    return { loading, refreshing, error, lastUpdated, refresh, paused, enabled };
}
